async probeAvailability(signal?: AbortSignal, opts: { timeoutMs?: number; preferAlternate?: boolean } = {}): Promise<ProbeResult> {
  const total = this.endpoints.length;
  const start = opts.preferAlternate && total > 1 ? (this.activeEndpointIndex + 1) % total : this.activeEndpointIndex;
  let last: ProbeResult = { available: false, condition: "TEMPORARILY_UNAVAILABLE" };
  for (let i = 0; i < total; i++) {
    const idx = (start + i) % total;
    last = await this.probeEndpointAt(idx, signal, opts.timeoutMs);
    if (last.available) {
      this.activeEndpointIndex = idx;
      return last;
    }
    // A transport failure that is not a temporary condition ends the walk; an HTTP error moves on to the next endpoint.
    if (last.httpStatus === undefined && !TEMPORARY_CONDITIONS.has(last.condition)) return last;
  }
  return last;
}

/**
 * Probes every endpoint of this connection (the primary and each failover) at once and keeps each result under its own
 * endpoint (endpoints `skip` names are not sent anything and are left out): one endpoint's failure never replaces another's answer. No side effects (the active endpoint stays).
 */
async probeEachEndpoint(signal?: AbortSignal, opts: { timeoutMs?: number; skip?: (endpoint: string) => boolean } = {}): Promise<Array<{ endpoint: string; probe: ProbeResult }>> {
  const all = [...this.endpoints].map((endpoint, idx) => ({ endpoint, idx })).filter(({ endpoint }) => !opts.skip?.(endpoint));
  return Promise.all(all.map(async ({ endpoint, idx }) => ({ endpoint, probe: await this.probeEndpointAt(idx, signal, opts.timeoutMs) })));
}

private async probeEndpointAt(idx: number, signal: AbortSignal | undefined, timeoutMs: number | undefined): Promise<ProbeResult> {
  const timeout = AbortSignal.timeout(timeoutMs ?? 5_000);
  try {
    const res = await this.fetchResendingStale(`${this.endpoints[idx]}/models`, {
      headers: this.authorization(this.endpoints[idx]),
      signal: signal ? AbortSignal.any([timeout, signal]) : timeout,
      ...this.fetchPolicy(),
    });
    const body = await res.text().catch(() => "");
    if (res.status < 500 && res.status !== 429 && res.status !== 408) {
      return { available: true, condition: "AVAILABLE", httpStatus: res.status };
    }
    const hints = providerHints(res.headers, body);
    return { ...classifyHttpFailure(res.status, hints, body), available: false, httpStatus: res.status, hints, detail: `HTTP ${res.status}` };
  } catch (err: any) {
    if (signal?.aborted) throw err;
    const chain = transportCauseChain(err);
    const { condition } = classifyTransportFailure(chain, "connect", err?.name === "TimeoutError");
    return { available: false, condition, detail: `${err?.message ?? err}${formatCause(chain)}`, ...(err?.name === "TimeoutError" ? { timedOut: true } : {}), codes: chain.flatMap((c) => (c.code ? [c.code] : [])) };
  }
}

async chatCompletion(
  messages: ChatMessage[],
  tools: ToolDefinition[],
  requestId: string = randomUUID(),
  signal?: AbortSignal,
  /** Receipt role override for auxiliary calls (e.g. "compaction"). */
  purpose?: string,
): Promise<ChatMessage> {
  await this.reverifyExpiredKind(signal);
  const response = await this.withReceipt(requestId, purpose, () =>
    this.withOAuthRetry(this.endpoint, requestId, () => this.withParameterRetry(() => this.chatCompletionOnce(messages, tools, requestId, signal))),
  );
  return this.askAgainForNativeCall(response, messages, tools, signal);
}

/**
 * A server that answered a tool request with the call as reply text (never executed, REQ-AGT-112) is asked again, at
 * most twice, and only a native call from an answer is used:
 * 1. with the reply and a note that text is not a call, `tool_choice` unchanged: a model that was only quoting JSON
 *    just answers, one that meant a call makes it natively;
 * 2. only if it wrote the call as text again after that note, with `tool_choice: required`.
 * The retry turns exist only in these requests, never in the returned history. A failed retry propagates like any
 * other request failure; with no native call the original reply stands.
 */
private async askAgainForNativeCall(response: ChatMessage, messages: ChatMessage[], tools: ToolDefinition[], signal?: AbortSignal): Promise<ChatMessage> {
  if (this.conn.protocol !== "openai-chat" || this.conn.streamOnly || !isContentCallReply(response, tools, messages)) return response;
  const corrected: ChatMessage[] = [...messages, { role: "assistant", content: response.content }, { role: "user", content: CONTENT_CALL_NOTE }];
  const ask = (toolChoice: "auto" | "required"): Promise<ChatMessage> => {
    const requestId = randomUUID();
    return this.withReceipt(requestId, "tool-call-retry", () =>
      this.withOAuthRetry(this.endpoint, requestId, () => this.withParameterRetry(() => this.chatCompletionOnce(corrected, tools, requestId, signal, toolChoice))),
    );
  };
  };
  this.emitDiagnostic("error", pc.dim(`[nexus] ${this.conn.label} answered a tool request with the call as text; telling it so and asking again.`));
